import {BUILDINGS,UNITS,unitStats} from './catalog.js';
import {mapSize} from './world.js';import {visibleAt}from'./fog.js';
export const ABILITIES={
 barrage:{name:'Bombardeo de área',description:'Ataque explosivo contra enemigos cercanos al objetivo.',range:12,radius:3,cooldown:28,cost:{supply:35},damage:220,delay:.8},
 airstrike:{name:'Apoyo aéreo',description:'Ataque aéreo sobre una zona descubierta. Requiere una radio capturada.',range:150,radius:5,cooldown:20,cost:{},damage:1800,delay:2},
 rally:{name:'Inspirar al pelotón',description:'Aumenta un 35% el daño de aliados cercanos durante 12 segundos.',range:8,radius:7,cooldown:40,cost:{supply:30},duration:12},
 stealth:{name:'Camuflaje',description:'Oculta al especialista durante 10 segundos. Atacar o acercarse a un detector lo revela.',range:0,cooldown:28,cost:{supply:20},duration:10},
 repair:{name:'Reparación de emergencia',description:'Restaura un 35% de integridad a máquinas y edificios aliados.',range:7,radius:3,cooldown:30,cost:{metal:30},heal:.35},
 medkit:{name:'Auxilio de campaña',description:'Cura un 30% de vida de la infantería aliada cercana.',range:7,radius:3,cooldown:28,cost:{supply:25},heal:.3},
 emp:{name:'Pulso electromagnético',description:'Daña y paraliza máquinas y torretas enemigas durante cuatro segundos.',range:9,radius:4,cooldown:40,cost:{supply:45},damage:120,duration:4},
 shield:{name:'Blindaje reforzado',description:'Reduce a la mitad el daño recibido durante ocho segundos.',range:0,cooldown:35,cost:{supply:25},duration:8},
 drones:{name:'Desplegar drones',description:'Invoca dos drones de apoyo temporales durante 40 segundos.',range:0,cooldown:60,cost:{metal:60,supply:40},duration:40},
 mine:{name:'Colocar mina',description:'Instala una carga que explota al acercarse un enemigo terrestre.',range:7,radius:2.5,cooldown:25,cost:{metal:25},damage:260},
 charge:{name:'Carga de choque',description:'Acelera al atacante y refuerza su daño durante seis segundos.',range:0,cooldown:30,cost:{supply:25},duration:6},
 lasers:{name:'Ráfaga multiláser',description:'Alcanza hasta cuatro blancos dentro de la zona marcada.',range:10,radius:4,cooldown:28,cost:{supply:35},damage:180},
 devour:{name:'Absorción vital',description:'Daña a un enemigo orgánico cercano y recupera vida con el daño causado.',range:5,radius:2,cooldown:40,cost:{supply:40},damage:350},
 vortex:{name:'Vórtice gravitatorio',description:'Atrae durante cuatro segundos a los enemigos de la zona, respetando sus rutas.',range:9,radius:4,cooldown:45,cost:{supply:45},duration:4},
 whirlwind:{name:'Torbellino',description:'Daño continuo contra enemigos cercanos durante seis segundos.',range:0,radius:2.5,cooldown:35,cost:{supply:30},duration:6}
};
export function unitAbilities(type){const u=UNITS[type];if(!u)return[];const name=u.name.toLowerCase(),out=[];if(u.repair)out.push('repair','mine');else if(u.heal)out.push('medkit');if(u.hero)out.push(u.range<3?'charge':'rally');if(u.stealth||type==='commando'||type==='scout'||/spy|special ops/.test(name))out.push('stealth');if(u.heavy&&!u.waterborne&&!u.flying)out.push('shield');if(u.weapon==='rocket'||/mortar|artillery|bomber|missile/.test(name))out.push('barrage');if(u.flying&&/drone|mech|nave|nemesis|némesis/.test(name))out.push('emp');if(/carrier|messiah|némesis|nemesis/.test(name)||type==='orbital')out.push('drones');if(/laser|blazer/.test(name))out.push('lasers');if(/devour|swamp|ether|soul/.test(name))out.push('devour');if(/nebular|vortex|gravity/.test(name))out.push('vortex');if(u.range<3&&/sword|axe|claw|karate|berserk/.test(name))out.push('whirlwind');return[...new Set(out)].slice(0,5);}
export const mechanical=a=>a.type in BUILDINGS||UNITS[a.type]?.heavy||UNITS[a.type]?.flying||UNITS[a.type]?.waterborne;
export function canTarget(observer,target,elapsed){if(target.embarked||target.evacuated||target.side==='neutral')return false;if((target.status?.stealth||0)<=elapsed)return true;const d=Math.hypot(observer.x-target.x,observer.y-target.y);return d<2.8||!!((UNITS[observer.type]?.seeStealth||BUILDINGS[observer.type]?.attack)&&d<4.5);}
export function availableAbilities(s,ids,side='player'){const b=s.battle;if(!b)return[];const actors=b.units.filter(u=>u.side===side&&u.hp>0&&!u.embarked&&ids.includes(u.id)),keys=[...new Set(actors.flatMap(u=>unitAbilities(u.type)))];if(side==='player'&&b.mission?.airSupport>0&&actors.length)keys.push('airstrike');return keys.map(id=>{const candidates=actors.filter(u=>id==='airstrike'||unitAbilities(u.type).includes(id)),ready=candidates.find(u=>(u.abilityCooldowns?.[id]||0)<=b.elapsed),remaining=Math.min(...candidates.map(u=>Math.max(0,(u.abilityCooldowns?.[id]||0)-b.elapsed)));return{id,...ABILITIES[id],ready:!!ready,remaining,caster:ready?.id};});}
export function createAbilities({makeUnit,log}){
 function damage(s,b,target,amount,source=null){if(target.hp<=0||!Number.isFinite(amount)||amount<=0||target.invulnerable)return 0;const shield=(target.status?.shield||0)>b.elapsed ? .5 : 1,value=Math.min(target.hp,Math.max(1,amount*shield));target.hp-=value;if(target.hp<=0){if(target.type in UNITS){if(target.side==='enemy'&&source?.side==='player')s.stats.kills++;if(target.side==='player'&&!target.loaned){s.stats.lost++;log(s,UNITS[target.type].name+' ha caído.');}b.dead||=[];b.dead.push({...target,at:b.elapsed});if(b.dead.length>64)b.dead.shift();}if(target.sourceId===948&&!target.exploded){target.exploded=true;for(const other of b.units.filter(u=>u.hp>0&&Math.hypot(u.x-target.x,u.y-target.y)<4))damage(s,b,other,350,source);}}return value;}
 function cast(s,ids,id,x,y,side='player'){const b=s.battle,definition=ABILITIES[id],choice=availableAbilities(s,ids,side).find(a=>a.id===id);if(!b||!definition||!choice)return{ok:false,message:'Esta selección no dispone de esa habilidad.'};if(id==='drones'&&b.units.filter(u=>u.hp>0).length+2>(b.kind==='network'?96:500))return{ok:false,message:'Se alcanzó el límite de unidades de apoyo.'};if(!choice.ready)return{ok:false,message:'La habilidad se recarga durante '+Math.ceil(choice.remaining)+' segundos.'};const caster=b.units.find(u=>u.id===choice.caster);if(!caster||caster.embarked)return{ok:false,message:'Selecciona una unidad desplegada.'};if(!definition.range){x=caster.x;y=caster.y;}if(!Number.isFinite(x)||!Number.isFinite(y)||x<1||y<1||x>=mapSize(b)-1||y>=mapSize(b)-1||Math.hypot(caster.x-x,caster.y-y)>definition.range+.1&&definition.range>0)return{ok:false,message:'Objetivo fuera del alcance de la habilidad.'};if(b.fog&&!visibleAt(b,x,y)&&id!=='stealth')return{ok:false,message:'Descubre esta zona antes de usar la habilidad.'};if(Object.entries(definition.cost).some(([k,v])=>s.resources[k]<v))return{ok:false,message:'Faltan materiales para utilizar esta habilidad.'};for(const[k,v]of Object.entries(definition.cost))s.resources[k]-=v;caster.abilityCooldowns||={};caster.abilityCooldowns[id]=b.elapsed+definition.cooldown;caster.status||={};
  const allies=b.units.filter(u=>u.side===side&&u.hp>0&&!u.embarked&&Math.hypot(u.x-x,u.y-y)<(definition.radius||1)),enemies=[...b.units,...b.buildings].filter(u=>u.side!==side&&u.side!=='neutral'&&u.hp>0&&Math.hypot(u.x-x,u.y-y)<(definition.radius||1));
  if(['shield','stealth','charge','whirlwind'].includes(id))caster.status[id]=b.elapsed+definition.duration;
  if(id==='rally')for(const u of allies){u.status||={};u.status.rally=b.elapsed+definition.duration;}
  if(id==='repair'||id==='medkit'){for(const u of[...allies,...(id==='repair'?b.buildings.filter(v=>v.side===side&&v.hp>0&&Math.hypot(v.x-x,v.y-y)<definition.radius):[])])if(id==='repair'?mechanical(u):!mechanical(u)){const max=u.maxHp||BUILDINGS[u.type].hp;u.hp=Math.min(max,u.hp+max*definition.heal);}}
  if(id==='emp')for(const u of enemies.filter(mechanical)){damage(s,b,u,definition.damage,caster);u.status||={};u.status.stun=b.elapsed+definition.duration;}
  if(id==='lasers')for(const u of enemies.slice(0,4))damage(s,b,u,definition.damage*(1+(caster.level-1)*.2),caster);
  if(id==='devour'){const target=enemies.find(u=>u.type in UNITS&&!mechanical(u));if(target){const dealt=damage(s,b,target,definition.damage,caster);caster.hp=Math.min(caster.maxHp,caster.hp+dealt*.6);}}
  if(id==='vortex')for(const u of enemies.filter(u=>u.type in UNITS)){u.status||={};u.status.pull={x,y,until:b.elapsed+definition.duration};}
  if(id==='mine'){b.mines||=[];if(b.mines.length>=30)b.mines.shift();b.mines.push({id:'mine-'+s.serial++,x,y,side,damage:definition.damage,radius:definition.radius,ends:b.elapsed+180});}
  if(id==='drones'){for(let i=0;i<2;i++){const u=makeUnit(s,'drone',caster.level);Object.assign(u,{id:'summon-'+s.serial++,x:caster.x+(i?1:-1),y:caster.y,side,owner:caster.owner,loaned:true,expires:b.elapsed+definition.duration,order:{kind:'assault',x,y}});b.units.push(u);}}
  if(id==='barrage'||id==='airstrike'){b.strikes||=[];b.strikes.push({x,y,side,radius:definition.radius,damage:definition.damage*(1+(caster.level-1)*.15),at:b.elapsed+definition.delay,caster:caster.id,kind:id});if(id==='airstrike')b.mission.airSupport--;}
  b.skillEffects||=[];b.skillEffects.push({x,y,side,kind:id,at:b.elapsed,radius:definition.radius||1});if(b.skillEffects.length>30)b.skillEffects.shift();return{ok:true,message:definition.name+' activado.'};
 }
 function tick(s,b,dt){b.dead=(b.dead||[]).filter(u=>b.elapsed-u.at<1.5);b.skillEffects=(b.skillEffects||[]).filter(e=>b.elapsed-e.at<2);for(const u of [...b.units,...b.buildings].filter(u=>u.hp>0)){if(u.expires&&u.expires<=b.elapsed){u.hp=0;continue;}const st=UNITS[u.type];if(st?.regenerate)u.hp=Math.min(u.maxHp,u.hp+u.maxHp*.01*dt);const dot=u.status?.dot;if(dot&&dot.until>b.elapsed-dt)damage(s,b,u,dot.dps*Math.min(dt,dot.until-(b.elapsed-dt)),{side:dot.side});if((u.status?.whirlwind||0)>b.elapsed)for(const target of b.units.filter(v=>v.hp>0&&v.side!==u.side&&v.side!=='neutral'&&!v.embarked&&Math.hypot(v.x-u.x,v.y-u.y)<2.5))damage(s,b,target,35*dt,u);}
  for(const strike of(b.strikes||[]).filter(e=>e.at<=b.elapsed)){for(const target of[...b.units,...b.buildings].filter(u=>u.hp>0&&u.side!==strike.side&&u.side!=='neutral'&&!u.embarked&&Math.hypot(u.x-strike.x,u.y-strike.y)<=strike.radius))damage(s,b,target,strike.damage,{side:strike.side});b.skillEffects.push({...strike,kind:'impact',at:b.elapsed});}b.strikes=(b.strikes||[]).filter(e=>e.at>b.elapsed);
  for(const mine of b.mines||[]){const enemy=b.units.find(u=>u.hp>0&&u.side!==mine.side&&u.side!=='neutral'&&!u.embarked&&!UNITS[u.type].flying&&Math.hypot(u.x-mine.x,u.y-mine.y)<1.1);if(!enemy)continue;for(const target of b.units.filter(u=>u.hp>0&&u.side!==mine.side&&u.side!=='neutral'&&!u.embarked&&Math.hypot(u.x-mine.x,u.y-mine.y)<mine.radius))damage(s,b,target,mine.damage,{side:mine.side});mine.ends=0;b.skillEffects.push({...mine,kind:'impact',at:b.elapsed});}b.mines=(b.mines||[]).filter(m=>m.ends>b.elapsed);b.units=b.units.filter(u=>!(u.expires&&u.hp<=0));
 }
 return{damage,cast,tick};
}
